   evidence.stage='returned-switch';await host.locator('[data-hd-oc-route-goal]').selectOption(scenario.targetGoal);evidence.selectionChangeCount++;await starterCarrierExpect(host.locator('[data-hd-oc-route-goal]')).toHaveValue(scenario.targetGoal);await starterCarrierExpect(host.locator('.hd-oc-result')).toHaveCount(0);await starterCarrierExpect(host.locator('[data-hd-oc-carrier-targets]')).toHaveCount(0);const returned=await inspect('returned','returned');expect(returned.ownRaw===controlled.ownExpectedRaw).toBe(true);ref.retainedOwnRaw=controlled.ownExpectedRaw;evidence.checkpoints.push({...returned.model,switchInvalidationExact:true});
